from pathlib import Path
import hashlib,json
p=Path.cwd();pins=json.loads((p/'evidence/inputs-before.json').read_text())
def sha(f):return hashlib.sha256(f.read_bytes()).hexdigest()
def tree(root):return {str(f.relative_to(root)):sha(f) for f in sorted(root.rglob('*')) if f.is_file()}
up=Path(pins['upstream']);contract=Path(pins['contract']);um=json.loads((up/'candidate-manifest.json').read_text());cm=json.loads((contract/'frozen/manifest.json').read_text())
changes={k for k,h in pins['upstream_source'].items() if sha(p/'src'/k)!=h}
