checks={'historical04dc_exact':sha(historical/'candidate-manifest.json')=='04dc571e8f79405f110e2117024bba191d50f6e4aedb6914f359cb71a9510faf' and all(sha(historical/f)==h for f,h in hm['files'].items()),'upstream_manifest_pin':sha(up/'candidate-manifest.json')==pins['upstream_manifest_sha256'],'upstream_manifest_complete':all(sha(up/f)==h for f,h in um['files'].items()),'contract_manifest_pin':sha(contract/'frozen/manifest.json')==pins['contract_manifest_sha256'],'contract3230_exact':len(cm['files'])==3230 and all(sha(contract/'frozen'/f)==h for f,h in cm['files'].items()),'actual105_exact':tree(Path(pins['actual_sdk']))==pins['actual105'],'installed181_exact':len(pins['guard181'])==181 and all(sha(Path(f))==h for f,h in pins['guard181'].items()),'protected_exact':all(sha(Path(f))==h for f,h in pins['protected'].items()),'source107_exact_except_builder':len(tree(p/'src'))==107 and changes=={'tx/update-price.ts'} and set(tree(p/'src'))==set(pins['upstream_source']),'unchanged76_test_files_exact':all(sha(p/'tests'/f)==h for f,h in pins['upstream_tests'].items()),'plain_source_and_tests':not any(f.is_symlink() for d in ['src','tests','upstream-evidence'] for f in (p/d).rglob('*')),'only_runtime_symlink':sorted(str(f.relative_to(p)) for f in p.rglob('*') if f.is_symlink())==['node_modules'],'original_tsconfig_exact':sha(p/'tsconfig.json')==pins['tsconfig_sha256'],'runtime_packages_exact':all(sha(Path(v['path']))==v['sha256'] for v in json.loads((p/'evidence/composition-inputs.json').read_text())['runtime'].values()),'package_pins_exact':all(sha(p/f)==h for f,h in json.loads((p/'evidence/baseline.json').read_text())['dependency_pins'].items()),'retained_abi_exact':sha(p/'upstream-evidence/market.move')==pins['abi_sha256']}
